create or replace function public.trg_quest_review_activity() returns trigger language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare v_eligible boolean:=false; v_checked timestamptz; begin if new.user_id is null then return new; end if; if new.check_in_id is null then return new; end if; select checked_in_at into v_checked from public.check_ins where id=new.check_in_id and user_id=new.user_id and location_id=new.location_id; if v_checked is null then return new; end if; v_eligible:=public.is_qualifying_return_visit(new.user_id,new.location_id,v_checked); if v_eligible then perform public.quest_advance_activity(new.user_id,'review',new.id,new.location_id,new.check_in_id,null,jsonb_build_object('stars',new.stars,'progression_eligible',true)); end if; return new; end; $function$;
comment on function public.trg_quest_review_activity() is 'Quest progression for reviews requires a valid associated check-in and the shared qualifying-return/daily-cap rule; review records themselves remain unrestricted.';
